#!/usr/bin/env python3
"""Deterministic C99 catalogue. --check never changes generated files."""
import argparse
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]

def generate():
    ps = json.loads((ROOT / 'share/providers.json').read_text(encoding='utf-8'))['providers']
    q = lambda s: json.dumps(s, ensure_ascii=False)
    rows = ['/* Generated by tools/gen-providers.py; edit share/providers.json. */']
    for n, p in enumerate(ps):
        rows.append(f'static const ui_model_t models_{n}[] = {{')
        rows.extend('    {%s, %d, %d},' % (q(m['id']), m['vision'], m['tools']) for m in p['models'])
        rows.append('};')
    rows.append('const ui_provider_t UI_PROVIDERS[] = {')
    rows.extend('    {%s, %s, %s, %d, %d, models_%d, %d},' %
                (q(p['id']),q(p['label']),q(p['base_url']),p['domestic'],p['adapter']=='openai',n,len(p['models'])) for n,p in enumerate(ps))
    rows.extend(['};', 'const size_t UI_PROVIDER_COUNT = sizeof UI_PROVIDERS / sizeof UI_PROVIDERS[0];', ''])
    return '\n'.join(rows)

if __name__ == '__main__':
    ap = argparse.ArgumentParser(); ap.add_argument('--check', action='store_true'); args = ap.parse_args()
    path = ROOT / 'kbd/providers.inc'; result = generate()
    if args.check:
        if path.read_text(encoding='utf-8') != result:
            raise SystemExit('providers.inc stale: run python3 deck/tools/gen-providers.py')
    else:
        path.write_text(result, encoding='utf-8')
